// Build editor brief card for each interview
const items = $input.all();
const briefs = [];

for (const item of items) {
  const props = item.json.properties || {};

  const guestName = props['Guest Name']?.title?.[0]?.plain_text || 'Unknown';
  const guestHandle = props['Guest IG Handle']?.rich_text?.[0]?.plain_text || '';
  const hookQuote = props['Hook Quote']?.rich_text?.[0]?.plain_text || '';
  const hookTimestamp = props['Hook Timestamp']?.rich_text?.[0]?.plain_text || '';
  const hookMomentNotes = props['Hook Moment Notes']?.rich_text?.[0]?.plain_text || '';
  const driveLink = props['Drive Link']?.url || props['Raw Video Link']?.url || '';
  const interviewType = props['Interview Type']?.select?.name || 'Street Interview';
  const postDate = props['Post Date']?.date?.start || 'TBD';

  const briefMessage = [
    `🎬 EDITOR BRIEF — ${guestName}`,
    `━━━━━━━━━━━━━━━━━━━━━`,
    `Guest: ${guestName}${guestHandle ? ' (' + guestHandle + ')' : ''}`,
    `Type: ${interviewType}`,
    `Target Post Date: ${postDate}`,
    ``,
    `🎯 HOOK`,
    `Quote: "${hookQuote}"`,
    `Timestamp: ${hookTimestamp}`,
    ``,
    `📝 EDITOR NOTES`,
    hookMomentNotes || 'See raw footage.',
    ``,
    `📁 RAW FOOTAGE`,
    driveLink || 'Check Google Drive — link TBD',
    ``,
    `📐 SPECS`,
    `Short-form: 30-90 sec, 9:16, hook in first 3 sec`,
    `Long-form: Full interview, 16:9, chapters every 3-5 min`,
    `Captions: White text, black outline, 1 word highlighted per phrase`,
    `Color: Warm, vibrant, natural skin tones`,
    `File name: BWH_${guestName.split(' ').pop()}_SF_v1.mp4`,
    ``,
    `Deliver to Google Drive. Reply when done. 💜`
  ].join('\n');

  briefs.push({
    json: {
      pageId: item.json.id,
      guestName,
      briefMessage
    }
  });
}

return briefs;
